insert into public.character_pool(content_key,category,text,value,scenario_tag,is_active)
values
('general_goal_v1:001','goal','Не просто пассажир — Войти в итоговый состав выживших и до финала объяснить конкретную полезную задачу, которую вы берёте на себя.',0,null,true),
('general_goal_v1:002','goal','Второй шанс — После первого публичного предложения исключить вас остаться среди выживших. Если такого предложения не было, войти в итоговый состав без него.',0,null,true),
('general_goal_v1:003','goal','Без громкого титула — Войти в итоговый состав, хотя бы раз обосновав свою пользу без ссылки на профессию.',0,null,true),
('general_goal_v1:004','goal','Честная цена — Раскрыть свою характеристику со стоимостью −1 и предложить способ учесть её недостаток. Если таких карт нет, назвать реальное ограничение своей полезной карты.',0,null,true),
('general_goal_v1:005','goal','Нужен именно я — До финала добиться, чтобы другой игрок своими словами назвал вашу конкретную задачу в плане выживания.',0,null,true),
('general_goal_v1:006','goal','Не один талант — Обосновать две разные полезные задачи для своего персонажа, опираясь на две разные раскрытые характеристики.',0,null,true),
('general_goal_v1:007','goal','Остаться собой — Войти в итоговый состав, не выдавая придуманное свойство карты за написанный на ней факт.',0,null,true),
('general_goal_v1:008','goal','Шанс для тихого — Предложить сохранить в группе другого участника, который ещё не выступал в текущем обсуждении, и помочь ему сформулировать пользу.',0,null,true),
('general_goal_v1:009','goal','Пережить сомнение — Попросить другого игрока назвать слабое место вашей кандидатуры и ответить на него конкретным планом до финала.',0,null,true),
('general_goal_v1:010','goal','Польза в мелочах — Предложить практическое применение своей раскрытой характеристики стоимостью 0. Если таких карт нет, предложить вспомогательную задачу для любой своей раскрытой карты.',0,null,true),
('general_goal_v1:011','goal','Не незаменимый — Назвать, кто из других участников может подменить вас хотя бы в одной задаче, и всё же обосновать ценность вашего присутствия.',0,null,true),
('general_goal_v1:012','goal','Не за чужой счёт — В своей последней защитной речи объяснить собственную пользу, не называя другого игрока бесполезным.',0,null,true),
('general_goal_v1:013','goal','Трудная пара — Показать, как ваша полезная характеристика и ваш недостаток могут быть учтены в одном реалистичном плане.',0,null,true),
('general_goal_v1:014','goal','Последнее слово по делу — В последнем своём выступлении до вердикта назвать действие, исполнителя и ограничение предложенного вами плана.',0,null,true),
('general_goal_v1:015','goal','Помощь остаётся — До финала передать группе полезный план с использованием своих раскрытых карт и назвать, как продолжить его, если вы не войдёте в состав выживших.',0,null,true),
('general_goal_v1:016','goal','Рабочий союз — Согласовать с другим игроком совместную задачу: каждый должен вслух подтвердить, какую часть работы берёт на себя.',0,null,true),
('general_goal_v1:017','goal','Недостающее звено — Найти полезное сочетание одной своей и одной чужой раскрытой характеристики и объяснить результат их совместного применения.',0,null,true),
('general_goal_v1:018','goal','Не приказ, а договор — Получить добровольное согласие другого участника помочь в предложенной вами задаче, предварительно назвав её риск.',0,null,true),
('general_goal_v1:019','goal','Разделение труда — Предложить общий план, в котором вы и другой игрок выполняете разные, не дублирующие друг друга функции.',0,null,true),
('general_goal_v1:020','goal','Доверенная работа — Поручить другому персонажу конкретную задачу на основании его раскрытой карты и получить его согласие.',0,null,true),
('general_goal_v1:021','goal','Общий язык — Попросить другого игрока пересказать ваш совместный план и вместе устранить хотя бы одно расхождение в понимании.',0,null,true),
('general_goal_v1:022','goal','Взаимная страховка — Согласовать с другим участником, как каждый из вас заметит ошибку второго и поможет её исправить.',0,null,true),
('general_goal_v1:023','goal','Учитель и ученик — Предложить обучение одному навыку, указанному на вашей раскрытой карте, и получить согласие другого участника обучаться без обещания мгновенного мастерства.',0,null,true),
('general_goal_v1:024','goal','Принять помощь — Публично назвать свою слабость и договориться с другим игроком о конкретной помощи в её обходе.',0,null,true),
('general_goal_v1:025','goal','Общий инструмент — Согласовать очередность использования одного раскрытого предмета для двух разных задач без его одновременного нахождения в двух местах.',0,null,true),
('general_goal_v1:026','goal','Союз без клятв — Обосновать сотрудничество с другим персонажем через взаимную пользу, не требуя обещания голосовать одинаково.',0,null,true),
('general_goal_v1:027','goal','Полезное соседство — Объяснить, почему ваши разные раскрытые умения позволяют работать вместе эффективнее, чем по отдельности, и получить ответ партнёра.',0,null,true),
('general_goal_v1:028','goal','Проверить согласие — Перед включением чужого персонажа в свой план спросить его согласие и изменить план с учётом ответа.',0,null,true),
('general_goal_v1:029','goal','Справедливый обмен — Предложить обмен помощью, в котором обе стороны вслух назовут получаемую пользу. Передавать карты при этом не обязательно.',0,null,true),
('general_goal_v1:030','goal','План на двоих — Вместе с другим участником представить один законченный способ решения общей проблемы: подготовка, действие и проверка результата.',0,null,true),
('general_goal_v1:031','goal','Проверяемое обещание — Заменить собственное общее обещание помочь конкретным действием, для которого названы средство и признак успеха.',0,null,true),
('general_goal_v1:032','goal','Сильное возражение — Сначала точно пересказать возражение другого игрока к вашему плану, получить подтверждение понимания, затем ответить по существу.',0,null,true),
('general_goal_v1:033','goal','Неочевидная польза — Показать полезное применение чужой раскрытой характеристики, которую до этого в обсуждении назвали ненужной.',0,null,true),
('general_goal_v1:034','goal','Без сверхспособностей — Отказаться от одного собственного преувеличения возможностей карты и предложить более ограниченный, но правдоподобный вариант.',0,null,true),
('general_goal_v1:035','goal','Цена решения — При защите своего предложения назвать не только выгоду, но и конкретную потерю или расход, с которым придётся согласиться.',0,null,true),
('general_goal_v1:036','goal','Два пути — Представить два разных способа решить одну общую проблему и объяснить, при каких условиях выбрать каждый.',0,null,true),
('general_goal_v1:037','goal','Аргумент принят — Добиться, чтобы другой игрок явно согласился хотя бы с одним вашим аргументом о полезности раскрытой карты, даже если он не согласен с вашим голосом.',0,null,true),
('general_goal_v1:038','goal','Право на сомнение — Назвать один вопрос, на который у вашего плана пока нет ответа, и предложить способ получить ответ до принятия решения.',0,null,true),
('general_goal_v1:039','goal','Поворот мнения — Изменить свою публичную оценку персонажа после новой раскрытой характеристики и объяснить, какой именно факт изменил мнение.',0,null,true),
('general_goal_v1:040','goal','Спор о действиях — В споре о составе сравнить конкретные задачи двух кандидатов, не переходя на оценку реальных людей за столом.',0,null,true),
('general_goal_v1:041','goal','Короткая защита — Один раз защитить свою кандидатуру тремя ясными пунктами: польза, ограничение, взаимодействие с группой.',0,null,true),
('general_goal_v1:042','goal','На чужом месте — Сформулировать сильный аргумент в пользу другого кандидата, даже если вы сами предпочитаете иной состав.',0,null,true),
('general_goal_v1:043','goal','Не путать факт и догадку — В одном своём плане отдельно назвать написанный на карте факт и предположение, которое группа ещё должна принять или проверить.',0,null,true),
('general_goal_v1:044','goal','Ответ вместо повтора — После вопроса о слабом месте своего плана дать новое пояснение, а затем спросить, сняло ли оно исходное возражение.',0,null,true),
('general_goal_v1:045','goal','Правило сравнения — Предложить один критерий выбора состава и применить его одинаково к себе и хотя бы одному другому персонажу.',0,null,true),
('general_goal_v1:046','goal','Сначала известное — До голосования отделить в обсуждаемом плане открытые сведения от ещё скрытых характеристик и не выдавать скрытое за доказанное.',0,null,true),
('general_goal_v1:047','goal','Важный вопрос — Задать другому игроку конкретный вопрос о применении его раскрытой карты и использовать полученный ответ в дальнейшей аргументации.',0,null,true),
('general_goal_v1:048','goal','Контекст недостатка — Раскрыть обычную характеристику с ограничением и сразу назвать, когда именно это ограничение станет опасным.',0,null,true),
('general_goal_v1:049','goal','Смотреть на текст — При разногласии о карте обратиться к её точной формулировке и добиться общего понимания хотя бы одного спорного ограничения.',0,null,true),
('general_goal_v1:050','goal','Что ещё неизвестно — Перед предложением итогового состава назвать хотя бы одно неизвестное, которое мешает уверенно оценить его шансы.',0,null,true),
('general_goal_v1:051','goal','Карта изменила план — После раскрытия новой характеристики другого игрока предложить конкретное изменение общего плана.',0,null,true),
('general_goal_v1:052','goal','Проверка слуха — Уточнить у владельца карты распространённое о ней утверждение и публично исправить его, если оно оказалось неточным.',0,null,true),
('general_goal_v1:053','goal','Открытая связность — При защите своего плана сослаться на две уже раскрытые карты и объяснить причинную связь между ними.',0,null,true),
('general_goal_v1:054','goal','Без чтения мыслей — Заменить собственное предположение о намерениях другого участника прямым вопросом и учесть его ответ.',0,null,true),
('general_goal_v1:055','goal','Найти противоречие — Указать на несовместимые допущения в одном плане и предложить способ устранить их без придумывания новой карты.',0,null,true),
('general_goal_v1:056','goal','Ранняя ясность — В своё первое доступное раскрытие обычной карты объяснить её пользу и границы применения до следующего своего раскрытия.',0,null,true),
('general_goal_v1:057','goal','Не скрывать условие — Предлагая применение своей карты, вслух назвать все ограничения её текста, относящиеся к этому применению.',0,null,true),
('general_goal_v1:058','goal','Сверить понимание — Попросить другого участника объяснить, как он понял одну вашу раскрытую карту, и при необходимости уточнить её смысл.',0,null,true),
('general_goal_v1:059','goal','Без тайного козыря — Хотя бы один раз обосновать своё место в составе только уже раскрытыми картами, не обещая спасительную скрытую характеристику.',0,null,true),
('general_goal_v1:060','goal','Полезное резюме — До финала кратко перечислить известные сильную сторону и ограничение другого персонажа и получить подтверждение владельца.',0,null,true),
('general_goal_v1:061','goal','Осмысленный голос — До своего первого поданного голоса объяснить его конкретной раскрытой характеристикой или проверяемым пробелом в плане группы.',0,null,true),
('general_goal_v1:062','goal','Сначала выслушать — Перед первым голосованием, в котором вы участвуете, задать кандидату вопрос о его пользе и дождаться ответа либо окончания его времени.',0,null,true),
('general_goal_v1:063','goal','Не по привычке — Не обосновывать ни один свой поданный голос только внешностью, именем или манерой речи реального участника.',0,null,true),
('general_goal_v1:064','goal','Защитить непопулярного — Публично привести конкретный аргумент за сохранение персонажа, которого другой участник уже предложил исключить.',0,null,true),
('general_goal_v1:065','goal','Проверить замену — Перед предложением исключить персонажа назвать, кто или что возьмёт на себя хотя бы одну его полезную функцию.',0,null,true),
('general_goal_v1:066','goal','Не обещать заранее — До первого голосования заявить, что оцените новые раскрытия, и хотя бы раз пересмотреть аргументы после появления новой карты.',0,null,true),
('general_goal_v1:067','goal','Объяснить разницу — Если ваш голос отличается от публичной позиции другого участника, спокойно объяснить конкретное различие критериев. Если позиции совпали, назвать собственный независимый аргумент.',0,null,true),
('general_goal_v1:068','goal','Не терять картину — Перед своим последним голосованием назвать одну задачу, которую должен уметь решать оставшийся состав.',0,null,true),
('general_goal_v1:069','goal','Голос без сделки — Хотя бы один раз подать голос по объяснённому критерию пользы, не заключая сделку о взаимном голосовании.',0,null,true),
('general_goal_v1:070','goal','Защита услышана — В своём аргументе перед голосованием прямо ответить хотя бы на один довод из защиты кандидата.',0,null,true),
('general_goal_v1:071','goal','Свой кандидат — До голосования самостоятельно предложить кандидатуру или явно отказаться от выдвижения, объяснив решение состоянием группы.',0,null,true),
('general_goal_v1:072','goal','При равных шансах — Предложить способ сравнить две кажущиеся равноценными кандидатуры через конкретный риск, а не через личную симпатию.',0,null,true),
('general_goal_v1:073','goal','Не по одной цифре — При оценке кандидата учесть одновременно полезную карту и ограничение; одной суммарной стоимости характеристик недостаточно.',0,null,true),
('general_goal_v1:074','goal','Ответственность за выбор — После своего первого голосования назвать возможную отрицательную сторону собственного решения, не перекладывая ответственность на большинство.',0,null,true),
('general_goal_v1:075','goal','Состав после потери — После исключения участника предложить, как группа закроет возникший пробел. Если исключений не было, заранее описать такой резерв для одного персонажа.',0,null,true),
('general_goal_v1:076','goal','Первые действия — Предложить последовательность первых трёх действий группы после выбора состава и объяснить их порядок.',0,null,true),
('general_goal_v1:077','goal','Запасной выход — К своему основному плану предложить альтернативу на случай отказа одного необходимого средства.',0,null,true),
('general_goal_v1:078','goal','Сначала проверить — Перед рискованным действием предложить малую проверку, позволяющую заметить ошибку до крупных потерь.',0,null,true),
('general_goal_v1:079','goal','Не всё одновременно — Обнаружить в обсуждаемом плане две задачи, требующие одного исполнителя или предмета, и согласовать их очередность.',0,null,true),
('general_goal_v1:080','goal','Условие остановки — Для одного опасного действия назвать понятный признак, при котором группа должна остановиться или отступить.',0,null,true),
('general_goal_v1:081','goal','Результат под проверкой — Назвать способ проверить успешность предложенного ремонта, обучения, подготовки или другой общей работы.',0,null,true),
('general_goal_v1:082','goal','Ближняя цель — Отделить в своём плане немедленную задачу от долгосрочной и объяснить, что позволит дожить до долгосрочного результата.',0,null,true),
('general_goal_v1:083','goal','Зависимость — Показать, какое действие нельзя начинать до завершения другого, и получить согласие хотя бы одного участника с такой очередностью.',0,null,true),
('general_goal_v1:084','goal','Один главный риск — Публично выбрать главную угрозу предложенному составу и объяснить, почему её нужно решать раньше остальных.',0,null,true),
('general_goal_v1:085','goal','Резервный исполнитель — Назвать подмену для одной критической задачи и объяснить, каких знаний или помощи этой подмене не хватает.',0,null,true),
('general_goal_v1:086','goal','Не потерять время — Указать, какое обещанное действие займёт время, и предложить, чем группа будет обеспечена до его завершения.',0,null,true),
('general_goal_v1:087','goal','План без чуда — Представить способ решения проблемы, который использует только доступные сведения и не требует внезапной находки редкого предмета.',0,null,true),
('general_goal_v1:088','goal','Проверка на отказ — Выбрать одно слабое место общего плана и описать, что произойдёт с группой при его отказе.',0,null,true),
('general_goal_v1:089','goal','Передать дело — Объяснить, какую информацию нужно передать другому персонажу, чтобы он смог продолжить одну вашу задачу.',0,null,true),
('general_goal_v1:090','goal','Финальная проверка — До вердикта проверить предложенный состав по трём вопросам: кто действует, чем действует и что ограничивает результат.',0,null,true),
('general_goal_v1:091','goal','Не бесконечный предмет — Назвать расход или износ одного раскрытого предмета и предложить способ продлить его полезность.',0,null,true),
('general_goal_v1:092','goal','Прежде чем тратить — Перед предложением расходовать общий запас объяснить ожидаемую пользу и доступную альтернативу.',0,null,true),
('general_goal_v1:093','goal','Сохранить резерв — Предложить, какую часть доступных средств или усилий стоит оставить на непредвиденный случай, и объяснить риск полного расхода.',0,null,true),
('general_goal_v1:094','goal','Удобный учёт — Предложить понятный способ учитывать один важный для группы запас без выдумывания его исходного количества.',0,null,true),
('general_goal_v1:095','goal','Предмет по назначению — Обосновать полезное применение раскрытого предмета в пределах его реальных свойств, не превращая его в универсальное решение.',0,null,true),
('general_goal_v1:096','goal','Два применения — Найти два разных правдоподобных применения одного раскрытого предмета и объяснить, можно ли использовать их последовательно.',0,null,true),
('general_goal_v1:097','goal','Ремонтопригодность — Показать, как доступное умение и доступное средство могут помочь обслуживать важную для группы вещь, назвав предел такого ремонта.',0,null,true),
('general_goal_v1:098','goal','Беречь руки — Предложить распределение физической нагрузки с учётом раскрытого ограничения хотя бы одного персонажа.',0,null,true),
('general_goal_v1:099','goal','Не портить хорошее — Назвать действие, которое может испортить полезный предмет или запас, и предложить меру предосторожности.',0,null,true),
('general_goal_v1:100','goal','Навык важнее вещи — Объяснить, какое умение нужно для применения одного раскрытого предмета и кто из доступных персонажей может его предоставить.',0,null,true),
('general_goal_v1:101','goal','Доступ важнее владения — Предложить порядок общего доступа к полезному предмету, при котором он не окажется одновременно обещан нескольким задачам.',0,null,true),
('general_goal_v1:102','goal','Небольшая экономия — Предложить конкретное сокращение расхода времени, сил или запасов без отказа от важной функции группы.',0,null,true),
('general_goal_v1:103','goal','Безопасное хранение — Назвать риск хранения одного доступного предмета или запаса и предложить подходящее место либо правило обращения.',0,null,true),
('general_goal_v1:104','goal','Проверить совместимость — Перед объединением двух средств в один план проверить, не мешают ли их свойства друг другу, и озвучить вывод.',0,null,true),
('general_goal_v1:105','goal','Считать честно — Исправить хотя бы одно собственное предположение о запасах, доступности предмета или объёме работы после проверки текста карт и условий.',0,null,true),
('general_goal_v1:106','goal','Одинаковая мерка — Публично применить к своей кандидатуре тот же критерий отбора, который вы предложили для других.',0,null,true),
('general_goal_v1:107','goal','Без ярлыков — Защитить право персонажа с раскрытым недостатком на обсуждение его реальной пользы, не отрицая сам недостаток.',0,null,true),
('general_goal_v1:108','goal','Обещание по силам — Дать одно конкретное обещание о своих действиях в обсуждении и выполнить его до финала.',0,null,true),
('general_goal_v1:109','goal','Признать ошибку — Самостоятельно исправить хотя бы одно своё неверное утверждение о карте, правилах или плане и объяснить правильный вариант.',0,null,true),
('general_goal_v1:110','goal','Разрешение на помощь — Прежде чем предлагать другому персонажу лечение, обучение или иную помощь, спросить его согласие и учесть ответ.',0,null,true),
('general_goal_v1:111','goal','Справедливое условие — Предложить общее правило распределения обязанностей, которое распространяется и на вашего персонажа.',0,null,true),
('general_goal_v1:112','goal','Не скрывать цену — Поддерживая чужой план, вслух назвать риск для своего персонажа, если он участвует в его выполнении.',0,null,true),
('general_goal_v1:113','goal','Уважить отказ — Получив отказ в предложенном сотрудничестве, предложить другой вариант без угроз взаимным голосованием. Если отказа нет, заранее назвать допустимую альтернативу.',0,null,true),
('general_goal_v1:114','goal','Не обещать чужое — Исправить план, где вы распорядились чужим умением или предметом без согласия владельца, либо получить такое согласие до принятия плана.',0,null,true),
('general_goal_v1:115','goal','Слабость не приговор — Объяснить, как группа может учитывать одну раскрытую фобию, болезнь или отрицательную черту, не объявляя персонажа автоматически бесполезным.',0,null,true),
('general_goal_v1:116','goal','Полезный оппонент — Признать конкретную полезную сторону персонажа участника, который не согласился с вами в обсуждении.',0,null,true),
('general_goal_v1:117','goal','Проверяемое доверие — Предложить способ доверить важную задачу персонажу так, чтобы результат можно было проверить, не требуя слепой веры.',0,null,true),
('general_goal_v1:118','goal','Не давить секретом — Хотя бы раз отстоять план открытыми аргументами, не используя угрозу раскрыть чужую личную информацию или цель.',0,null,true),
('general_goal_v1:119','goal','Право на поправку — Предложить другому игроку уточнить своё неудачное высказывание перед тем, как использовать его против его кандидатуры.',0,null,true),
('general_goal_v1:120','goal','Честный итог — Перед вердиктом назвать одну сильную сторону выбранного состава и одно оставшееся сомнение, не объявляя исход заранее гарантированным.',0,null,true),
('general_goal_v1:121','goal','Вернуть к задаче — После ухода обсуждения от условий игры предложить конкретный вопрос о выживании и получить хотя бы один содержательный ответ.',0,null,true),
('general_goal_v1:122','goal','Дать договорить — Предложить выслушать участника, которого перебили, и дождаться завершения его ответа либо окончания выделенного времени.',0,null,true),
('general_goal_v1:123','goal','Свести позиции — Кратко сформулировать две разные позиции в споре и уточнить у их сторонников, правильно ли вы их поняли.',0,null,true),
('general_goal_v1:124','goal','Общий список — Предложить короткий список задач группы и добиться, чтобы другой участник добавил или уточнил хотя бы один пункт.',0,null,true),
('general_goal_v1:125','goal','Не говорить за всех — Выдвинув общий план, прямо спросить хотя бы одного другого участника о возражениях и учесть ответ.',0,null,true),
('general_goal_v1:126','goal','Найти согласие — В споре о составе назвать пункт, с которым согласны вы и ваш оппонент, и получить его подтверждение.',0,null,true),
('general_goal_v1:127','goal','Снять недоразумение — Помочь двум участникам понять, спорят ли они о факте карты или о способе её применения, и вслух обозначить различие.',0,null,true),
('general_goal_v1:128','goal','Порядок вопросов — Предложить сначала решить один конкретный спорный вопрос и только затем переходить к зависящему от него выбору.',0,null,true),
('general_goal_v1:129','goal','Проверка готовности — Перед предложением завершить обсуждение спросить, остался ли важный неотвеченный вопрос, и дать возможность его озвучить.',0,null,true),
('general_goal_v1:130','goal','Удержать суть — После длинного обсуждения сформулировать главный ещё не решённый вопрос одним предложением и получить ответ другого игрока.',0,null,true),
('general_goal_v1:131','goal','Слово другому — Попросить другого участника представить его собственный план вместо того, чтобы снова повторять свой, и обсудить полученный вариант.',0,null,true),
('general_goal_v1:132','goal','Согласовать термины — Уточнить значение одного неоднозначного слова в обсуждении плана, чтобы участники не опирались на разные трактовки.',0,null,true),
('general_goal_v1:133','goal','Записать решение — Попросить зафиксировать важную договорённость в общем чате или хронике и проверить, что запись соответствует сказанному.',0,null,true),
('general_goal_v1:134','goal','Спокойная пауза — При возникновении путаницы предложить кратко подвести промежуточный итог без перехода к новому голосованию или новой теме.',0,null,true),
('general_goal_v1:135','goal','Законченный ответ — На один вопрос другого игрока дать полный ответ по существу и спросить, требуется ли уточнение, прежде чем менять тему.',0,null,true),
('general_goal_v1:136','goal','Призвание — В своей защите связать профессию персонажа с конкретной задачей группы и назвать границу профессиональных возможностей.',0,null,true),
('general_goal_v1:137','goal','Хобби пригодилось — Предложить правдоподобную пользу раскрытого хобби своего персонажа и получить хотя бы один ответ на это предложение.',0,null,true),
('general_goal_v1:138','goal','Прошлое помогает — Связать один раскрытый факт биографии своего персонажа с выбором конкретного действия в плане группы.',0,null,true),
('general_goal_v1:139','goal','Черта в деле — Объяснить, как раскрытая черта характера вашего персонажа повлияет на распределение обязанностей, учитывая и её возможный минус.',0,null,true),
('general_goal_v1:140','goal','Багаж с историей — Назвать причину, по которой персонаж хранит один свой раскрытый предмет, и предложить его полезное применение без добавления новых свойств.',0,null,true),
('general_goal_v1:141','goal','Предел выносливости — Предложить подходящую своему раскрытому здоровью нагрузку и способ не сорвать общую задачу при ухудшении состояния.',0,null,true),
('general_goal_v1:142','goal','Справиться со страхом — Объяснить, как учитывать свою раскрытую фобию в плане. Если фобия не раскрывалась, предложить общий порядок помощи испуганному персонажу без обещания мгновенного излечения.',0,null,true),
('general_goal_v1:143','goal','Новая роль — До финала предложить для своего персонажа полезную обязанность, которая не сводится к буквальному названию его профессии.',0,null,true),
('general_goal_v1:144','goal','Опыт без всезнания — Использовать раскрытый факт о своём опыте как аргумент, одновременно назвав область, в которой этот опыт не делает вас специалистом.',0,null,true),
('general_goal_v1:145','goal','Привычка на пользу — Предложить, как хобби или черта своего персонажа поможет поддерживать повседневный порядок в выбранной группе.',0,null,true),
('general_goal_v1:146','goal','Личная граница — Назвать одну задачу, за которую ваш персонаж не может ответственно взяться по раскрытым картам, и предложить допустимую замену.',0,null,true),
('general_goal_v1:147','goal','Не самый сильный — Обосновать место своего персонажа через аккуратность, организацию или обучение, не ссылаясь на превосходство в силе или здоровье.',0,null,true),
('general_goal_v1:148','goal','Переосмысление — Изменить собственный первоначальный план для персонажа после раскрытия чужой карты и объяснить причину изменения.',0,null,true),
('general_goal_v1:149','goal','Наследие знаний — До финала объяснить, какое знание из раскрытого опыта вашего персонажа стоит передать группе независимо от вашего попадания в итоговый состав.',0,null,true),
('general_goal_v1:150','goal','Обещание будущему — Перед вердиктом назвать конкретное посильное дело, которым ваш персонаж займётся после устранения ближайшей угрозы, и связать его с раскрытой характеристикой.',0,null,true)
